import { useLeadResource } from '../hooks/useLeadResource';
import { useLeadUpdates } from '../hooks/useLeadUpdates';
import React, { useEffect, useMemo, useRef, useState } from "react";
import { useLocation, useNavigate, useParams } from "react-router-dom";
import { toast } from "sonner";
import { ArrowLeft, Building2, Download, Loader2, Mail, MessageSquarePlus, Pencil, Phone, UserCheck, UserPlus, X } from "lucide-react";
import SummaryApi from "../common";
import AdminWorkspaceShell, { AdminWorkspaceHeader } from "../components/admin/AdminWorkspaceShell";
import AdminInfoPill from "../components/admin/AdminInfoPill";
import EditLeadModal from "../components/admin/EditLeadModal";
import KeyboardSelect from "../components/KeyboardSelect";
import KeyboardHint from "../components/KeyboardHint";
import { goToAdminReturn } from "../helpers/adminReturnNavigation";
import { LEAD_CACHE, patchCachedRow } from "../utils/resourceCache";
import DataSpinner from "../components/admin/DataSpinner";
import UpdatingSign from "../components/admin/UpdatingSign";
import isAccountEmail from "../helpers/accountEmail";
import { clientBehaviourOptions, DEFAULT_CLIENT_BEHAVIOUR, DEFAULT_LEAD_STATUS, leadStatusLabel, leadStatusOptions, leadStatusStyle, offerStageOptions } from "../helpers/leadStatuses";
import LeadProposals from "../components/admin/LeadProposals";
import ProposalSentBadge from "../components/admin/ProposalSentBadge";
import { whatsappChatHref } from "../helpers/whatsappChat";

const formatDateTime = (value) => {
  if (!value) return "N/A";
  return new Date(value).toLocaleString("en-IN");
};

const AdminLeadDetailPage = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const { leadId } = useParams();

  const [lead, setLead] = useState(null);
  const [finalMessageBusy, setFinalMessageBusy] = useState(false);
  const [showStopCountdown, setShowStopCountdown] = useState(false);
  const [stopReason, setStopReason] = useState("");
  const [stoppingCountdown, setStoppingCountdown] = useState(false);
  const [finalCountdown, setFinalCountdown] = useState("");
  const [messageBusy, setMessageBusy] = useState(false);

  const [followUpNote, setFollowUpNote] = useState("");
  const [followUpBadge, setFollowUpBadge] = useState("");
  const [followUpFile, setFollowUpFile] = useState(null);
  const [followUpOffer, setFollowUpOffer] = useState("");
  const [timelineTab, setTimelineTab] = useState("all");
  const [followUpSaving, setFollowUpSaving] = useState(false);
  const [converting, setConverting] = useState(false);
  const [showConvertConfirm, setShowConvertConfirm] = useState(false);
  const [showUpgradeConfirm, setShowUpgradeConfirm] = useState(false);
  // The website account the backend found for this lead: by its email, or by its phone (then its own email).
  const [upgradeAccount, setUpgradeAccount] = useState({ email: "", byPhone: false });
  // null = closed; "edit" = Edit Lead button; "convert" = opened by Convert for a missing field.
  const [editLeadMode, setEditLeadMode] = useState(null);
  const [editingFollowUpId, setEditingFollowUpId] = useState(null);
  const [editNote, setEditNote] = useState("");
  const [editBadge, setEditBadge] = useState("");
  const [editSaving, setEditSaving] = useState(false);

  const followUpBadgeRef = useRef(null);
  const followUpFileRef = useRef(null);
  const followUpNoteRef = useRef(null);
  const followUpSubmitRef = useRef(null);
  const editBadgeRef = useRef(null);
  const editNoteRef = useRef(null);
  const editSubmitRef = useRef(null);

  // Enter on a text field moves to the next field; a textarea keeps Shift+Enter
  // for a real newline. Shared with AdminLeadsPage's Add Lead form pattern —
  // see DOCS/context-keyboard.md.
  const focusNextOnEnter = (nextRef) => (event) => {
    if (event.key !== "Enter" || event.shiftKey) return;
    event.preventDefault();
    nextRef.current?.focus();
  };

  // Shown in the header only until the full lead arrives. It never goes into `lead`:
  // the actions below must stay closed until the contact block and final message are known.
  const leadPreview = location.state?.leadPreview?._id === leadId ? location.state.leadPreview : null;
  const badgeChosen = useRef(false);
  const focusedOnce = useRef(false);

  const { refresh: fetchLead, loading, refreshing: updating, error: refreshError, confirmed, expired } = useLeadResource(
    `${SummaryApi.leadDetail.url}/${leadId}`, (data, initial) => {
      setLead(data);
      if (data) {
        const { name, nameFromWhatsapp, businessName, phone, altPhone, email, source, status, updatedAt, proposalSentAt, clientBehaviour, convertedToUserId } = data;
        patchCachedRow(SummaryApi.adminLeads.url, data._id, { name, nameFromWhatsapp, businessName, phone, altPhone, email, source, status, updatedAt, proposalSentAt, clientBehaviour, convertedToUserId });
      }
      // Live reads must not overwrite an in-progress follow-up selection. "Initial" is also the first
      // current answer after kept data, which corrects the kept stage unless the admin already chose one.
      if (initial && !badgeChosen.current) setFollowUpBadge(data?.convertedToUserId ? data.clientBehaviour || DEFAULT_CLIENT_BEHAVIOUR : data?.status || DEFAULT_LEAD_STATUS);
    }, { cache: LEAD_CACHE });
  const shownLead = expired ? null : lead || leadPreview;
  // Kept data can be read at once, but nothing is acted on until it is confirmed current.
  const actionsOpen = Boolean(lead) && confirmed && !expired;
  // A client's phone and email are their account's (getLeadDetail.js sends lead.client); the lead holds a copy.
  const contactPhone = lead?.client?.phone || lead?.phone;
  const contactEmail = lead?.client?.email || lead?.email;
  const chatHref = actionsOpen ? whatsappChatHref(contactPhone) : null;
  const altChatHref = actionsOpen ? whatsappChatHref(lead?.altPhone) : null;
  const liveStatus = useLeadUpdates(() => { void fetchLead(); }, leadId);

  const isConverted = Boolean(lead?.convertedToUserId);
  const isMatured = isConverted || lead?.status === "Won";
  // One current status for the panel and the follow-up form: a client's status, or a lead's stage.
  const currentStatus = isConverted ? lead?.clientBehaviour || DEFAULT_CLIENT_BEHAVIOUR : lead?.status;

  const offerTargets = useMemo(() => lead?.offerTargets || [], [lead]);
  const targetFor = (slug) => offerTargets.find((row) => row.offerSlug === slug);
  const chosenTarget = targetFor(followUpOffer);

  // Choosing an offer means the stage below is that offer's. General goes back to the lead's own.
  const chooseFollowUpOffer = (slug) => {
    badgeChosen.current = true;
    setFollowUpOffer(slug);
    setFollowUpBadge(targetFor(slug)?.stage || currentStatus || DEFAULT_LEAD_STATUS);
  };

  // The server words every outcome other than an opened popup (updateLead.js finalMessageNote).
  const noticeFinalMessage = (note) => {
    if (note) toast.info(note);
  };

  const finalMessage = lead?.finalMessage;
  useEffect(() => {
    if (finalMessage?.status !== "waiting" || !finalMessage.deadlineAt || !lead?.serverNow) { setFinalCountdown(""); return; }
    const remaining = Date.parse(finalMessage.deadlineAt) - Date.parse(lead.serverNow);
    const started = performance.now();
    const update = () => {
      const seconds = Math.max(0, Math.ceil((remaining - (performance.now() - started)) / 1000));
      setFinalCountdown(seconds ? `${Math.floor(seconds / 3600)}h ${Math.floor(seconds / 60) % 60}m ${seconds % 60}s remaining`
        : finalMessage.listening === false ? "Time is up. WhatsApp is offline: Dead is decided when it reconnects." : "Time is up. Checking for a reply now…");
    };
    update();
    const timer = setInterval(update, 1000);
    return () => clearInterval(timer);
  }, [finalMessage?.status, finalMessage?.deadlineAt, finalMessage?.listening, lead?.serverNow]);
  const finalMessageAction = !actionsOpen ? null : finalMessage?.status === "review" ? "Review final message" : lead?.finalMessageCanStart ? "Start final message" : null;
  const finalMessageLine = !finalMessage ? (currentStatus === "Negative" ? "Not started. No countdown is running." : "") : {
    review: "Waiting for your Send or Don't Send. The countdown has not started.",
    queued: "Queued on WhatsApp. The countdown starts when it sends.",
    waiting: `Sent. Waiting for a reply; ${isConverted ? "the current status" : "the lead"} moves to Dead after ${finalMessage.deadlineAt ? new Date(finalMessage.deadlineAt).toLocaleString("en-IN", { timeZone: "Asia/Kolkata", dateStyle: "medium", timeStyle: "short" }) : "the wait"}.`,
    replied: finalMessage.decision ? `Replied: "${finalMessage.lastReplyText || "Message"}". Decision made.` : `Replied: "${finalMessage.lastReplyText || "Message"}". Decide in Communication → Final Message.`,
    dead: `No reply in time. ${isConverted ? "Current status" : "Stage"} moved to Dead.`,
    "not-sent": "Not sent. No countdown is running.",
    "email-only": "Sent by email only, so no countdown runs.",
    stopped: `Stopped${finalMessage.stopReason ? `: ${finalMessage.stopReason}` : "."}`,
  }[finalMessage.status] || "";
  // Shown while it concerns the person now: Negative or Dead, or a cycle that can still be stopped.
  const showFinalMessage = ["Negative", "Dead"].includes(currentStatus) || Boolean(finalMessage?.stopLabel) || ["review", "queued", "waiting"].includes(finalMessage?.status);

  // The popup opens from this response (helpers/emailReview.js), and the timeline shows the line once it closes.
  const sendMessage = async () => {
    try {
      setMessageBusy(true);
      const response = await fetch(`${SummaryApi.updateLead.url}/${leadId}/message`, { method: "post", credentials: "include" });
      const result = await response.json();
      if (!result.success) toast.error(result.message || "The message could not be prepared");
      await fetchLead();
    } catch (error) {
      console.error("Error preparing the message:", error);
      toast.error("The message could not be prepared");
    } finally {
      setMessageBusy(false);
    }
  };

  const sendFinalMessage = async () => {
    try {
      setFinalMessageBusy(true);
      const response = await fetch(`${SummaryApi.updateLead.url}/${leadId}/final-message`, { method: "post", credentials: "include" });
      const result = await response.json();
      if (!result.success) toast.error(result.message || "The final message could not be prepared");
      await fetchLead();
    } catch (error) {
      console.error("Error preparing the final message:", error);
      toast.error("The final message could not be prepared");
    } finally {
      setFinalMessageBusy(false);
    }
  };

  const stopCountdown = async (event) => {
    event.preventDefault();
    if (!stopReason.trim()) return;
    setStoppingCountdown(true);
    try {
      const response = await fetch(`${SummaryApi.updateLead.url}/${leadId}/final-message/stop`, { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ draftId: finalMessage.draftId, reason: stopReason.trim() }) });
      const result = await response.json();
      if (!response.ok || !result.success) throw new Error(result.message || 'Countdown could not be stopped.');
      setShowStopCountdown(false); setStopReason('');
      toast.success(`${finalMessage.stopLabel === 'Cancel closure message' ? 'Closure message cancelled' : 'Stopped'}. Current status is unchanged.`);
      await fetchLead();
    } catch (error) { toast.error(error.message); }
    finally { setStoppingCountdown(false); }
  };

  const handleAddFollowUp = async (event) => {
    event.preventDefault();
    if (!followUpNote.trim()) {
      toast.error("Please write a follow-up note");
      return;
    }
    try {
      setFollowUpSaving(true);
      // Multipart so the optional file rides along in the same request; adding the
      // follow-up also moves the lead's stage to the chosen badge (backend merge).
      const formData = new FormData();
      formData.append("action", "followUp");
      formData.append("badge", chosenTarget || isConverted ? followUpBadge : isMatured ? "Won" : followUpBadge);
      formData.append("note", followUpNote);
      if (chosenTarget) formData.append("offerSlug", chosenTarget.offerSlug);
      if (followUpFile) {
        formData.append("attachment", followUpFile);
      }

      const response = await fetch(`${SummaryApi.updateLead.url}/${leadId}`, {
        method: SummaryApi.updateLead.method,
        credentials: "include",
        body: formData,
      });
      const result = await response.json();
      if (!result.success) {
        toast.error(result.message || "Failed to add follow-up");
        return;
      }
      toast.success("Follow-up added");
      noticeFinalMessage(result.finalMessageNote);
      setFollowUpNote("");
      setFollowUpFile(null);
      await fetchLead();
    } catch (error) {
      console.error("Error adding follow-up:", error);
      toast.error("Error adding follow-up");
    } finally {
      setFollowUpSaving(false);
    }
  };

  const startEditFollowUp = (item) => {
    setEditingFollowUpId(item._id);
    setEditNote(item.note || "");
    setEditBadge(item.badge || DEFAULT_LEAD_STATUS);
  };

  useEffect(() => {
    if (editingFollowUpId) {
      editBadgeRef.current?.focus();
    }
  }, [editingFollowUpId]);

  // Follow-up entry is this page's main keyboard task, so focus lands there as
  // soon as the lead (and its default Stage selection) has loaded.
  useEffect(() => {
    if (!loading && lead && !focusedOnce.current) {
      // Once per opening: a background refresh must not pull focus from a note being typed.
      focusedOnce.current = true;
      followUpBadgeRef.current?.focus();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [loading, lead]);

  const cancelEditFollowUp = () => {
    if (editSaving) return;
    setEditingFollowUpId(null);
    setEditNote("");
    setEditBadge("");
  };

  const handleSaveEditFollowUp = async (event) => {
    event.preventDefault();
    if (!editBadge) {
      toast.error("Please select a stage badge");
      return;
    }
    if (!editNote.trim()) {
      toast.error("Please write a follow-up note");
      return;
    }
    try {
      setEditSaving(true);
      const formData = new FormData();
      formData.append("action", "editFollowUp");
      formData.append("followUpId", editingFollowUpId);
      formData.append("badge", editBadge);
      formData.append("note", editNote);

      const response = await fetch(`${SummaryApi.updateLead.url}/${leadId}`, {
        method: SummaryApi.updateLead.method,
        credentials: "include",
        body: formData,
      });
      const result = await response.json();
      if (!result.success) {
        toast.error(result.message || "Failed to update follow-up");
        return;
      }
      toast.success("Follow-up updated");
      noticeFinalMessage(result.finalMessageNote);
      setEditingFollowUpId(null);
      setEditNote("");
      setEditBadge("");
      await fetchLead();
    } catch (error) {
      console.error("Error updating follow-up:", error);
      toast.error("Error updating follow-up");
    } finally {
      setEditSaving(false);
    }
  };

  // A client account needs a confirmed name (not one guessed from WhatsApp), a phone and a valid
  // email; when any is missing, Convert opens Edit Lead first and continues to the confirm step on save.
  const isReadyToConvert = (target) => Boolean(target?.name?.trim()) && !target?.nameFromWhatsapp && Boolean(target?.phone?.trim()) && isAccountEmail(target?.email || "");

  const requestConvert = () => {
    if (!actionsOpen || converting || isConverted) return;
    if (!isReadyToConvert(lead)) {
      setEditLeadMode("convert");
      return;
    }
    setShowConvertConfirm(true);
  };

  const handleLeadSaved = async (savedLead) => {
    const continueToConvert = editLeadMode === "convert";
    setEditLeadMode(null);
    await fetchLead();
    if (continueToConvert && isReadyToConvert(savedLead)) {
      setShowConvertConfirm(true);
    }
  };

  const closeConvertConfirm = () => {
    if (converting) return;
    setShowConvertConfirm(false);
    setShowUpgradeConfirm(false);
  };

  // upgradeExisting: the admin confirmed turning an existing blog-only website
  // account with this email into the client account (backend code EXISTING_MEMBER).
  const handleConvert = async (upgradeExisting = false) => {
    if (!actionsOpen || converting) return;

    try {
      setConverting(true);
      const response = await fetch(`${SummaryApi.convertLead.url}/${leadId}/convert`, {
        method: SummaryApi.convertLead.method,
        credentials: "include",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ upgradeExisting }),
      });
      const result = await response.json();
      if (!result.success) {
        if (result.code === "EXISTING_MEMBER") {
          setUpgradeAccount({ email: result.accountEmail || lead?.email || "", byPhone: result.matchedBy === "phone" });
          setShowConvertConfirm(false);
          setShowUpgradeConfirm(true);
          return;
        }
        toast.error(result.message || "Failed to convert lead");
        return;
      }
      toast.success(
        `${result.data?.upgradedExisting ? "Website account turned into a client." : "Client created."} Login email: ${result.data?.email} · Password: ${result.data?.defaultPassword}`
      );
      setShowConvertConfirm(false);
      setShowUpgradeConfirm(false);
      await fetchLead();
    } catch (error) {
      console.error("Error converting lead:", error);
      toast.error("Error converting lead");
    } finally {
      setConverting(false);
    }
  };

  const followUps = useMemo(() => {
    const list = (lead?.followUps || []).filter((item) => timelineTab === "all" || (timelineTab === "general" ? !item.offerSlug : item.offerSlug === timelineTab));
    return [...list].sort((a, b) => new Date(b.createdAt || 0) - new Date(a.createdAt || 0));
  }, [lead, timelineTab]);

  const stopCountdownControl = actionsOpen && finalMessage?.stopLabel ? <div>
    {showStopCountdown ? <form onSubmit={stopCountdown} className="space-y-2">
      <label className="block text-sm font-semibold">Reason for stopping<textarea aria-label="Reason for stopping" maxLength={500} required value={stopReason} onChange={event => setStopReason(event.target.value)} placeholder="For example: client asked us to stop closure during a phone call" className="mt-1 w-full rounded-xl border border-slate-300 p-2" /></label>
      <p className="text-xs text-slate-500">{finalMessage.stopLabel === 'Cancel closure message' ? 'The closure message will not be sent.' : 'Ends this final message and cancels anything not yet sent.'} Current status stays the same.</p>
      <button type="submit" disabled={stoppingCountdown || !stopReason.trim()} className="rounded-xl border border-red-200 px-3 py-2 text-sm font-semibold text-red-700 disabled:opacity-50">{stoppingCountdown ? 'Stopping…' : 'Confirm stop'}</button>
      <button type="button" disabled={stoppingCountdown} onClick={() => setShowStopCountdown(false)} className="ml-2 px-3 py-2 text-sm">Cancel</button>
    </form> : <button type="button" onClick={() => setShowStopCountdown(true)} className="rounded-xl border border-red-200 px-3 py-2 text-sm font-semibold text-red-700">{finalMessage.stopLabel}</button>}
  </div> : null;

  const finalMessageBlock = showFinalMessage ? (
    <div className="mt-4 space-y-2 border-t border-slate-100 pt-4" aria-label="Final message">
      <h4 className="text-xs font-bold uppercase tracking-wide text-slate-500">Final message</h4>
      {finalMessageLine ? <p className="text-xs font-medium text-slate-700">{finalMessageLine}</p> : null}
      {finalCountdown ? <p className="text-sm font-semibold tabular-nums" aria-label="Final message countdown">{finalCountdown}</p> : null}
      {isConverted && currentStatus === "Negative" && lead?.finalMessageReadiness?.ready === false ? <p role="status" className="text-xs font-medium text-amber-800">{lead.finalMessageReadiness.message}</p> : null}
      {finalMessageAction ? (
        <button
          type="button"
          onClick={sendFinalMessage}
          disabled={finalMessageBusy}
          className="rounded-2xl border border-slate-200 px-4 py-2 text-sm font-semibold text-slate-700 transition hover:bg-slate-100 disabled:opacity-60"
        >
          {finalMessageAction}
        </button>
      ) : null}
      {stopCountdownControl}
    </div>
  ) : null;

  return (
    <>
      <AdminWorkspaceShell>
        <UpdatingSign show={updating && !loading} />
        {(refreshError || liveStatus === 'unavailable') && <p role="status" className="px-5 py-2 text-sm">{refreshError || 'Live updates temporarily unavailable.'} <button type="button" onClick={() => void fetchLead()}>Refresh</button></p>}
        <AdminWorkspaceHeader
          icon={isConverted ? UserCheck : UserPlus}
          eyebrow={isConverted ? "Client" : "Lead"}
          title={shownLead?.name || shownLead?.businessName || shownLead?.phone || (loading ? "Loading..." : "Lead")}
          subtitle={[shownLead?.name ? shownLead?.businessName : "", shownLead?.email || shownLead?.phone].filter(Boolean).join(" · ")}
          leadingAction={
            <button
              type="button"
              onClick={() => goToAdminReturn(navigate, location, "/admin-panel/leads")}
              className="inline-flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl border border-white/10 bg-white/5 text-white transition hover:bg-white/10"
              aria-label="Go back"
            >
              <ArrowLeft size={18} />
            </button>
          }
          meta={
            <>
              <AdminInfoPill label={isConverted ? "Identity" : "Status"} value={isConverted ? "Client" : shownLead || !loading ? leadStatusLabel(shownLead?.status) : "..."} variant="dark" />
              <AdminInfoPill label="Source" value={shownLead?.source || (loading ? "..." : "N/A")} variant="dark" />
              <AdminInfoPill label="Added" value={lead?.createdAt ? new Date(lead.createdAt).toLocaleDateString("en-IN") : loading ? "..." : "N/A"} variant="dark" />
            </>
          }
          actions={
            actionsOpen ? (
              <button
                type="button"
                onClick={() => setEditLeadMode("edit")}
                className="inline-flex w-full items-center justify-center gap-2 rounded-2xl border border-white/10 bg-white/10 px-4 py-3 text-sm font-semibold text-white transition hover:bg-white/15 lg:w-auto"
              >
                <Pencil size={16} />
                {isConverted ? "Edit Details" : "Edit Lead"}
              </button>
            ) : null
          }
        />

        {/* Hidden, not removed: a note being typed survives while too-old data is replaced. */}
        {loading ? <DataSpinner floating /> : null}
        <div hidden={expired} data-lead-body="1" className={expired ? "" : "grid grid-cols-1 gap-6 p-5 sm:p-6 lg:grid-cols-3"}>
          {/* Left: lead info + pipeline */}
          <div className="space-y-6 lg:col-span-1">
            <div className="rounded-3xl border border-slate-200 bg-white p-5">
              <h3 className="text-sm font-bold uppercase tracking-wide text-slate-500">Contact</h3>
              <div className="mt-3 space-y-3">
                {lead?.nameFromWhatsapp ? (
                  <p className="text-xs font-medium text-amber-700">Name taken from WhatsApp, not confirmed. Save it in Edit Lead to confirm.</p>
                ) : null}
                {lead?.businessName ? (
                  <div className="flex items-center gap-3 text-sm text-slate-800">
                    <Building2 size={16} className="text-slate-400" />
                    <span className="truncate">{lead.businessName}</span>
                  </div>
                ) : null}
                <div className="flex items-center gap-3 text-sm text-slate-800">
                  <Mail size={16} className="text-slate-400" />
                  <span className="truncate">{contactEmail || (loading ? "..." : "N/A")}</span>
                </div>
                <div className="flex items-center gap-3 text-sm text-slate-800">
                  <Phone size={16} className="text-slate-400" />
                  <span className="truncate">{contactPhone || (loading ? "..." : "N/A")}</span>
                </div>
                {chatHref ? (
                  <a
                    href={chatHref}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="inline-flex items-center gap-2 rounded-2xl border border-emerald-200 bg-emerald-50 px-4 py-2.5 text-sm font-semibold text-emerald-700 transition hover:bg-emerald-100 focus-visible:outline-none focus-visible:ring-4 focus-visible:ring-emerald-200"
                  >
                    <MessageSquarePlus size={16} />
                    Open WhatsApp chat
                  </a>
                ) : actionsOpen ? (
                  <p className="text-xs text-slate-500">Add a valid phone number with country code to open WhatsApp chat.</p>
                ) : null}
                {lead?.altPhone ? (
                  <>
                    <div className="flex items-center gap-3 text-sm text-slate-800">
                      <Phone size={16} className="text-slate-400" />
                      <span className="truncate">{lead.altPhone}</span>
                      <span className="text-xs text-slate-500">Alternate</span>
                    </div>
                    {altChatHref ? (
                      <a
                        href={altChatHref}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="inline-flex items-center gap-2 rounded-2xl border border-emerald-200 bg-emerald-50 px-4 py-2.5 text-sm font-semibold text-emerald-700 transition hover:bg-emerald-100 focus-visible:outline-none focus-visible:ring-4 focus-visible:ring-emerald-200"
                      >
                        <MessageSquarePlus size={16} />
                        Open WhatsApp chat
                      </a>
                    ) : null}
                  </>
                ) : null}
              </div>
              {lead?.inquiry ? (
                <div className="mt-4 border-t border-slate-100 pt-4 text-sm text-slate-700">
                  <h4 className="text-xs font-bold uppercase tracking-wide text-slate-500">WhatsApp ad message</h4>
                  <p className="mt-2 break-words text-slate-800">{lead.inquiry.message}</p>
                  <p className="mt-2 text-xs text-slate-500">
                    {lead.inquiry.firstAt ? new Date(lead.inquiry.firstAt).toLocaleString("en-IN") : ""}
                    {lead.inquiry.lastAt && lead.inquiry.lastAt !== lead.inquiry.firstAt ? ` · last message ${new Date(lead.inquiry.lastAt).toLocaleString("en-IN")}` : ""}
                  </p>
                  {lead.inquiry.profileName ? <p className="mt-1 text-xs text-slate-500">WhatsApp name: {lead.inquiry.profileName} (may not be their real name)</p> : null}
                </div>
              ) : null}
              {lead?.notes ? (
                <div className="mt-4 border-t border-slate-100 pt-4">
                  <h4 className="text-xs font-bold uppercase tracking-wide text-slate-500">Notes</h4>
                  <p className="mt-2 whitespace-pre-wrap text-sm text-slate-700">{lead.notes}</p>
                </div>
              ) : null}
            </div>

            <div className="rounded-3xl border border-slate-200 bg-white p-5">
              <h3 className="text-sm font-bold uppercase tracking-wide text-slate-500">{isConverted ? "Client" : "Current Stage"}</h3>
              {isConverted ? (
                <div className="mt-3 space-y-3">
                  <p className="rounded-2xl bg-emerald-50 px-4 py-3 text-sm text-emerald-700">
                    Client account · projects, payments and follow-ups remain linked.
                  </p>
                  <div className="space-y-2">
                    <p className="text-xs font-semibold uppercase tracking-wide text-slate-500">Current status</p>
                    <span className={["inline-flex rounded-full border px-4 py-1.5 text-sm font-semibold", leadStatusStyle(currentStatus)].join(" ")}>
                      {leadStatusLabel(currentStatus)}
                    </span>
                    <p className="text-xs text-slate-500">Change the status on a follow-up. Matured stays.</p>
                  </div>
                  {lead.clientAvailable !== false ? <button
                    type="button"
                    onClick={() => navigate(`/admin-panel/clients/${lead.convertedToUserId}`)}
                    className="inline-flex w-full items-center justify-center gap-2 rounded-2xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm font-semibold text-emerald-700 transition hover:bg-emerald-100"
                  >
                    <UserCheck size={16} />
                    View Client
                  </button> : <p className="text-xs text-slate-500">Linked client is unavailable.</p>}
                </div>
              ) : (
                <div className="mt-3 space-y-2">
                  <span
                    className={[
                      "inline-flex rounded-full border px-4 py-1.5 text-sm font-semibold",
                      leadStatusStyle(lead?.status),
                    ].join(" ")}
                  >
                    {lead || !loading ? leadStatusLabel(lead?.status) : "..."}
                  </span>
                  <p className="text-xs text-slate-500">
                    Change the stage on a follow-up. Adding a proposal never changes it.
                  </p>
                </div>
              )}
              {finalMessageBlock}
              {lead?.proposalSentAt ? (
                <div className="mt-3">
                  <ProposalSentBadge className="px-4 py-1.5 text-sm" />
                </div>
              ) : null}
              {lead?.contactBlock ? (
                <div className="mt-3">
                  <span className="inline-flex rounded-full border border-slate-300 bg-slate-200 px-4 py-1.5 text-sm font-semibold text-slate-700">{lead.contactBlock.label}</span>
                  <p className="mt-2 text-xs text-slate-500">{lead.contactBlock.message}</p>
                </div>
              ) : null}
              <button
                type="button"
                onClick={sendMessage}
                disabled={messageBusy || !actionsOpen || Boolean(lead?.contactBlock)}
                className="mt-3 rounded-2xl border border-slate-200 px-4 py-2 text-sm font-semibold text-slate-700 transition hover:bg-slate-100 disabled:cursor-not-allowed disabled:opacity-60"
              >
                Send message
              </button>
              {lead?.nameFromWhatsapp ? <p className="mt-2 text-xs font-medium text-amber-700">Name not confirmed: messages go without a name until you save it in Edit Lead.</p> : null}
            </div>

            {offerTargets.length ? (
              <div className="rounded-3xl border border-slate-200 bg-white p-5">
                <h3 className="text-sm font-bold uppercase tracking-wide text-slate-500">Offers</h3>
                <ul className="mt-3 space-y-2">
                  {offerTargets.map((row) => (
                    <li key={row.offerSlug} className="flex items-center justify-between gap-2 text-sm text-slate-800">
                      <span className="min-w-0 break-words">{row.offerTitle || row.offerSlug}</span>
                      <span className={["inline-flex shrink-0 rounded-full border px-3 py-1 text-xs font-semibold", leadStatusStyle(row.stage)].join(" ")}>{leadStatusLabel(row.stage)}</span>
                    </li>
                  ))}
                </ul>
              </div>
            ) : null}

            <LeadProposals lead={lead} loading={loading} readOnly={isConverted} actionsOpen={actionsOpen} onChanged={fetchLead} />

            {!isConverted ? (
              <div className="rounded-3xl border border-slate-200 bg-white p-5">
                <h3 className="text-sm font-bold uppercase tracking-wide text-slate-500">Convert</h3>
                <p className="mt-2 text-xs text-slate-500">
                  Creates a customer account (default password <span className="font-semibold">1234</span>). Requires phone and email.
                </p>
                <button
                  type="button"
                  onClick={requestConvert}
                  disabled={converting || !actionsOpen}
                  className="mt-3 inline-flex w-full items-center justify-center gap-2 rounded-2xl bg-emerald-600 px-4 py-3 text-sm font-semibold text-white transition hover:bg-emerald-700 disabled:cursor-not-allowed disabled:opacity-60"
                >
                  <UserCheck size={16} />
                  Convert to Client
                </button>
                {lead && !isReadyToConvert(lead) ? (
                  <p className="mt-2 text-xs text-amber-600">
                    {!lead.name?.trim()
                      ? "Name missing — Convert will ask for it."
                      : lead.nameFromWhatsapp
                        ? "Name is from WhatsApp — Convert will ask you to confirm it."
                        : !lead.phone?.trim()
                          ? "Phone missing — Convert will ask for it."
                          : "Valid email missing — Convert will ask for it."}
                  </p>
                ) : null}
              </div>
            ) : null}
          </div>

          {/* Right: follow-up log */}
          <div className="lg:col-span-2">
            <div className="rounded-3xl border border-slate-200 bg-white p-5">
              <h3 className="text-sm font-bold uppercase tracking-wide text-slate-500">Follow-ups</h3>

              {lead ? (
                <form onSubmit={handleAddFollowUp} className="mt-3 space-y-3">
                  {offerTargets.length ? (
                    <div>
                      <label className="mb-1.5 block text-xs font-semibold uppercase tracking-wide text-slate-500">For</label>
                      <KeyboardSelect
                        value={followUpOffer}
                        onChange={chooseFollowUpOffer}
                        options={[{ value: "", label: "General" }, ...offerTargets.map((row) => ({ value: row.offerSlug, label: row.offerTitle || row.offerSlug }))]}
                        onConfirm={() => followUpBadgeRef.current?.focus()}
                      />
                    </div>
                  ) : null}
                  {/* Stage + file side by side; remark below (full width). */}
                  <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
                    {/* Stage badge (dropdown) — colored so the timeline flow is readable. */}
                    <div>
                      <label className="mb-1.5 block text-xs font-semibold uppercase tracking-wide text-slate-500">
                        {isConverted && !chosenTarget ? "Status" : "Stage"}
                      </label>
                      <KeyboardSelect
                        ref={followUpBadgeRef}
                        value={chosenTarget || isConverted ? followUpBadge : isMatured ? "Won" : followUpBadge}
                        onChange={(value) => { badgeChosen.current = true; setFollowUpBadge(value); }}
                        options={chosenTarget ? offerStageOptions(chosenTarget.stage) : isConverted ? clientBehaviourOptions(currentStatus) : isMatured ? [{ value: "Won", label: "Matured", className: leadStatusStyle("Won") }] : leadStatusOptions(lead?.status)}
                        onConfirm={() => followUpFileRef.current?.focus()}
                        className="font-semibold"
                      />
                      <KeyboardHint id="hint-followup-stage" hint="Press ↓ or Enter to open · ↑↓ to move · Enter to select" />
                    </div>

                    {/* Optional attachment for this follow-up. */}
                    <div>
                      <label className="mb-1.5 block text-xs font-semibold uppercase tracking-wide text-slate-500">
                        Attachment <span className="font-normal normal-case text-slate-400">(optional)</span>
                      </label>
                      <input
                        ref={followUpFileRef}
                        type="file"
                        onChange={(e) => setFollowUpFile(e.target.files?.[0] || null)}
                        onKeyDown={(event) => {
                          if (event.key !== "Enter") return;
                          event.preventDefault();
                          followUpNoteRef.current?.focus();
                        }}
                        className="peer block w-full rounded-2xl border border-slate-200 bg-slate-50 py-2.5 pl-3 text-sm text-slate-700 file:mr-3 file:rounded-xl file:border-0 file:bg-slate-100 file:px-4 file:py-2 file:text-sm file:font-semibold file:text-slate-700 hover:file:bg-slate-200"
                      />
                      <KeyboardHint id="hint-followup-attachment" hint="Space to browse files · Enter to continue" />
                    </div>
                  </div>

                  {/* Remark (last, full width). */}
                  <div>
                    <textarea
                      ref={followUpNoteRef}
                      onKeyDown={focusNextOnEnter(followUpSubmitRef)}
                      value={followUpNote}
                      onChange={(e) => setFollowUpNote(e.target.value)}
                      placeholder="Add a follow-up note (call summary, next step, etc.)"
                      rows={3}
                      className="peer w-full rounded-2xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm text-slate-900 outline-none transition focus:border-emerald-400 focus:bg-white focus:ring-4 focus:ring-emerald-100"
                    />
                    <KeyboardHint id="hint-followup-note" hint="Enter for next field · Shift+Enter for new line" />
                  </div>

                  <div className="flex justify-end">
                    <button
                      ref={followUpSubmitRef}
                      type="submit"
                      disabled={followUpSaving || !actionsOpen}
                      className="inline-flex items-center gap-2 rounded-2xl bg-emerald-600 px-5 py-2.5 text-sm font-semibold text-white transition hover:bg-emerald-700 focus:animate-pulse focus:outline-none focus:ring-4 focus:ring-emerald-300 disabled:opacity-60"
                    >
                      <MessageSquarePlus size={16} />
                      {followUpSaving ? "Adding..." : "Add Follow-up"}
                    </button>
                  </div>
                </form>
              ) : null}

              {offerTargets.length ? (
                <div className="mt-5 flex flex-wrap gap-2" role="group" aria-label="Show follow-ups for">
                  {[{ id: "all", label: "All" }, { id: "general", label: "General" }, ...offerTargets.map((row) => ({ id: row.offerSlug, label: row.offerTitle || row.offerSlug }))].map((tab) => (
                    <button
                      key={tab.id}
                      type="button"
                      aria-pressed={timelineTab === tab.id}
                      onClick={() => setTimelineTab(tab.id)}
                      className={[
                        "rounded-full px-4 py-1.5 text-xs font-semibold transition",
                        timelineTab === tab.id ? "bg-emerald-600 text-white" : "bg-slate-100 text-slate-600 hover:bg-slate-200",
                      ].join(" ")}
                    >
                      {tab.label}
                    </button>
                  ))}
                </div>
              ) : null}

              <div className="mt-5 space-y-3">
                {followUps.length === 0 ? (
                  <p className="rounded-2xl bg-slate-50 px-4 py-6 text-center text-sm text-slate-500">
                    {loading ? "Loading..." : "No follow-ups yet."}
                  </p>
                ) : (
                  followUps.map((item, index) => (
                    <div key={item._id || index} className="rounded-2xl border border-slate-200 bg-slate-50 p-4">
                      {editingFollowUpId === item._id ? (
                        <form onSubmit={handleSaveEditFollowUp} className="space-y-3">
                          <div>
                            <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
                              <KeyboardSelect
                                ref={editBadgeRef}
                                value={editBadge}
                                onChange={(value) => setEditBadge(value)}
                                options={item.offerSlug ? offerStageOptions(targetFor(item.offerSlug)?.stage, item.badge) : isMatured ? [{ value: item.badge, label: leadStatusLabel(item.badge), className: leadStatusStyle(item.badge) }] : leadStatusOptions(item.badge)}
                                onConfirm={() => editNoteRef.current?.focus()}
                                className="font-semibold"
                              />
                            </div>
                            <KeyboardHint id="hint-editfollowup-stage" hint="Press ↓ or Enter to open · ↑↓ to move · Enter to select" />
                          </div>
                          <div>
                            <textarea
                              ref={editNoteRef}
                              onKeyDown={focusNextOnEnter(editSubmitRef)}
                              value={editNote}
                              onChange={(e) => setEditNote(e.target.value)}
                              rows={3}
                              className="peer w-full rounded-2xl border border-slate-200 bg-white px-4 py-3 text-sm text-slate-900 outline-none transition focus:border-emerald-400 focus:ring-4 focus:ring-emerald-100"
                            />
                            <KeyboardHint id="hint-editfollowup-note" hint="Enter for next field · Shift+Enter for new line" />
                          </div>
                          <div className="flex justify-end gap-2">
                            <button
                              type="button"
                              onClick={cancelEditFollowUp}
                              disabled={editSaving}
                              className="inline-flex items-center gap-1.5 rounded-2xl border border-slate-200 bg-white px-4 py-2.5 text-sm font-semibold text-slate-700 transition hover:bg-slate-100 disabled:opacity-60"
                            >
                              <X size={14} />
                              Cancel
                            </button>
                            <button
                              ref={editSubmitRef}
                              type="submit"
                              disabled={editSaving}
                              className="inline-flex items-center gap-1.5 rounded-2xl bg-emerald-600 px-4 py-2.5 text-sm font-semibold text-white transition hover:bg-emerald-700 focus:animate-pulse focus:outline-none focus:ring-4 focus:ring-emerald-300 disabled:opacity-60"
                            >
                              {editSaving ? "Saving..." : "Save"}
                            </button>
                          </div>
                        </form>
                      ) : (
                        <>
                          <div className="flex flex-wrap items-center justify-between gap-2">
                            <div className="flex flex-wrap items-center gap-2">
                              {item.badge ? (
                                <span
                                  className={[
                                    "inline-flex rounded-full border px-3 py-1 text-xs font-semibold",
                                    leadStatusStyle(item.badge),
                                  ].join(" ")}
                                >
                                  {isConverted && item.badge === "Won" && !item.offerSlug ? "Client" : leadStatusLabel(item.badge)}
                                </span>
                              ) : null}
                              {item.offerSlug ? (
                                <span className="inline-flex rounded-full border border-slate-200 bg-white px-3 py-1 text-xs font-semibold text-slate-600">
                                  {targetFor(item.offerSlug)?.offerTitle || item.offerSlug}
                                </span>
                              ) : null}
                            </div>
                            {actionsOpen && !item.messageDraftId ? (
                              <button
                                type="button"
                                onClick={() => startEditFollowUp(item)}
                                className="inline-flex items-center gap-1 rounded-xl px-2 py-1 text-xs font-semibold text-slate-500 transition hover:bg-slate-200 hover:text-slate-700"
                              >
                                <Pencil size={13} />
                                Edit
                              </button>
                            ) : null}
                          </div>
                          <p className="mt-2 whitespace-pre-wrap text-sm text-slate-800">{item.note}</p>
                          {item.attachment?.downloadLink ? (
                            <a
                              href={item.attachment.downloadLink}
                              target="_blank"
                              rel="noopener noreferrer"
                              className="mt-3 inline-flex items-center gap-1.5 rounded-xl border border-slate-200 bg-white px-3 py-2 text-xs font-semibold text-slate-700 transition hover:bg-slate-100"
                            >
                              <Download size={14} />
                              <span className="max-w-[200px] truncate">{item.attachment.name || "Attachment"}</span>
                            </a>
                          ) : null}
                          <p className="mt-2 text-xs text-slate-500">
                            {item.createdBy?.name ? `${item.createdBy.name} · ` : ""}
                            {formatDateTime(item.createdAt)}
                          </p>
                        </>
                      )}
                    </div>
                  ))
                )}
              </div>
            </div>
          </div>
        </div>
      </AdminWorkspaceShell>

      {showConvertConfirm && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/60 p-4">
          <div className="w-full max-w-md rounded-3xl bg-white shadow-2xl">
            <div className="px-6 pt-6">
              <div className="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl bg-emerald-100 text-emerald-600">
                <UserCheck size={24} />
              </div>
              <h2 className="mt-4 text-center text-lg font-bold text-slate-900">Convert lead to client?</h2>
              <p className="mt-2 text-center text-sm text-slate-600">
                <span className="font-semibold text-slate-900">{lead?.name || "This lead"}</span> will get a new
                customer account with the default password <span className="font-semibold">1234</span>. The client
                can set their own password on first login.
              </p>
            </div>

            <div className="flex justify-center gap-3 px-6 py-6">
              <button
                type="button"
                onClick={closeConvertConfirm}
                disabled={converting}
                className="rounded-2xl border border-slate-200 px-5 py-3 text-sm font-semibold text-slate-700 transition hover:bg-slate-100 disabled:opacity-60"
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={() => handleConvert(false)}
                disabled={converting}
                className="inline-flex items-center gap-2 rounded-2xl bg-emerald-600 px-5 py-3 text-sm font-semibold text-white transition hover:bg-emerald-700 disabled:cursor-not-allowed disabled:opacity-60"
              >
                {converting ? <Loader2 size={16} className="animate-spin" /> : <UserCheck size={16} />}
                {converting ? "Converting..." : "Convert to Client"}
              </button>
            </div>
          </div>
        </div>
      )}

      {showUpgradeConfirm && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/60 p-4">
          <div className="w-full max-w-md rounded-3xl bg-white shadow-2xl">
            <div className="px-6 pt-6">
              <div className="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl bg-amber-100 text-amber-600">
                <UserCheck size={24} />
              </div>
              <h2 className="mt-4 text-center text-lg font-bold text-slate-900">{upgradeAccount.byPhone ? "Phone already has a website account" : "Email already has a website account"}</h2>
              <p className="mt-2 text-center text-sm text-slate-600">
                <span className="font-semibold text-slate-900">{upgradeAccount.email || lead?.email}</span> already signed up on the website{upgradeAccount.byPhone ? " with this lead's phone number. That email becomes the client's login" : ""}.
                Turn that account into this client's account? It keeps its website profile, and its password is reset to
                the default <span className="font-semibold">1234</span> — the client sets their own on first login.
              </p>
            </div>

            <div className="flex justify-center gap-3 px-6 py-6">
              <button
                type="button"
                onClick={closeConvertConfirm}
                disabled={converting}
                className="rounded-2xl border border-slate-200 px-5 py-3 text-sm font-semibold text-slate-700 transition hover:bg-slate-100 disabled:opacity-60"
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={() => handleConvert(true)}
                disabled={converting}
                className="inline-flex items-center gap-2 rounded-2xl bg-emerald-600 px-5 py-3 text-sm font-semibold text-white transition hover:bg-emerald-700 disabled:cursor-not-allowed disabled:opacity-60"
              >
                {converting ? <Loader2 size={16} className="animate-spin" /> : <UserCheck size={16} />}
                {converting ? "Converting..." : "Use This Account"}
              </button>
            </div>
          </div>
        </div>
      )}

      {editLeadMode && lead ? (
        <EditLeadModal
          lead={lead}
          forConvert={editLeadMode === "convert"}
          onClose={() => setEditLeadMode(null)}
          onSaved={handleLeadSaved}
        />
      ) : null}
    </>
  );
};

export default AdminLeadDetailPage;
